import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import { cells, clock, hitPercent, minutesLeft, tone } from './meter'

const reading = atom({ plugin: 'cache-meter', key: 'reading' } as const, null)
// Bumped every 30s so the countdown redraws while nothing else is happening.
const tick = atom({ plugin: 'cache-meter', key: 'tick' } as const, 0)

// The session's last response carries the cache counts; `summary` estimates
// locally and sends no request. `fresh` says the response just arrived.
async function sample($: EngineInterface, fresh: boolean) {
  const { context } = await $.session.usage({ breakdown: 'summary' })
  const u = context.breakdown?.apiUsage
  const hit = u ? hitPercent(u) : null
  if (!u || hit === null || u.cache_read_input_tokens + u.cache_creation_input_tokens === 0) return
  const at = fresh ? await $.clock.now() : null
  // A seed never overwrites a reading that already knows its time.
  await update($, reading, prev => (fresh || prev === null ? { at, hitPercent: hit } : prev))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    await sample($, false)
    $.clock.every(30_000, () => update($, tick, n => n + 1))
    return result
  })

  // Fires on every response that moves the context fill: a fresh cache reading.
  on('session.measure', async ($, e, next) => {
    if (e.changed.includes('context')) await sample($, true)
    return next(e)
  })

  on('session.compact', async ($, e, next) => {
    // The compacted transcript is a new prefix: the old cache no longer applies.
    await update($, reading, () => null)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    // Keep what a plugin beneath drew (context-weather) and stack ours on top, so both show.
    const below = await next(e)
    const r = await read($, reading)
    await read($, tick)
    if (e.props.hasSurvey) return below

    const { Box, Text, Button } = $.ui.resolve(e)
    const known = r !== null && r.at !== null
    const mins = known ? minutesLeft(r.at as number, await $.clock.now()) : 0
    const color = !known ? undefined : mins === 0 ? 'error' : tone(mins)
    const width = Math.max(8, Math.min(30, e.props.bodyColumns - 48))
    const [full, empty] = cells(known ? mins : 0, width)
    const canCompact = !e.props.isWorking

    const band = (
      <Box flexDirection="row" justifyContent="space-between">
        <Box flexDirection="row">
          <Text color={color ?? 'success'} dimColor={!known}>
            ●{' '}
          </Text>
          <Text color={color} dimColor={!known} bold>
            {!known ? '--' : mins === 0 ? 'cold' : `${clock(mins)} left`}
          </Text>
          <Text color={color}> {full}</Text>
          <Text dimColor>{empty}</Text>
        </Box>
        <Box flexDirection="row">
          <Text dimColor>cache </Text>
          <Text bold>{r === null ? '--' : r.hitPercent}%</Text>
          <Text dimColor> hit </Text>
          {canCompact ? (
            <Button key="compact" label="Compact" hotkey="k" onPress={() => $.session.compact()} />
          ) : null}
        </Box>
      </Box>
    )

    // A blank row above our line, so it clears the spinner, and one between
    // our line and the band beneath, so the two don't crowd.
    return (
      <Box flexDirection="column" marginTop={1} gap={1}>
        {band}
        {below}
      </Box>
    )
  })
}

