// The prompt cache lives this long after each response that touches it.
export const TTL_MS = 60 * 60 * 1000

export function hitPercent(u: {
  input_tokens: number
  cache_read_input_tokens: number
  cache_creation_input_tokens: number
}): number | null {
  const total = u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens
  return total === 0 ? null : Math.round((u.cache_read_input_tokens / total) * 100)
}

export function minutesLeft(at: number, now: number): number {
  return Math.max(0, Math.ceil((at + TTL_MS - now) / 60_000))
}

export function clock(minutes: number): string {
  if (minutes >= 60) return `${Math.floor(minutes / 60)}h${String(minutes % 60).padStart(2, '0')}`
  return `${minutes}m`
}

// One cell per slice of the TTL: filled while that slice of cache life remains.
export function cells(minutes: number, width: number): [string, string] {
  const filled = Math.max(0, Math.min(width, Math.ceil((minutes / (TTL_MS / 60_000)) * width)))
  return ['▪'.repeat(filled), '▫'.repeat(width - filled)]
}

export function tone(minutes: number): 'success' | 'warning' | 'error' {
  if (minutes <= 5) return 'error'
  if (minutes <= 15) return 'warning'
  return 'success'
}

