export type CacheReading = {
  /** Epoch ms when the response that produced this reading arrived; null when seeded from a past response. */
  at: number | null
  /** Share of the last response's prompt served from cache, 0 to 100. */
  hitPercent: number
}

declare module 'claude-code' {
  interface PluginState {
    'cache-meter': { reading: CacheReading | null; tick: number }
  }
}
